contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint prePot = c.pot(); if (__ESBMC_reverted()) return;
        uint preBal = address(c).balance;

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint postPot = c.pot(); if (__ESBMC_reverted()) return;
        uint postBal = address(c).balance;

        assert(
            (reverted && amount != 10 && postPot == prePot && postBal == preBal) ||
            (!reverted && amount == 10 && (
                (postBal == preBal + 10 && postPot == prePot + 10) ||
                (postBal == preBal - prePot && postPot == 0)
            ))
        );
    }

    receive() external payable {}
}

